export function useDiesisStakingApprovalEvent(address: Address, listener: (log: any) => void) {
  return useWatchContractEvent({
    address,
    abi: DiesisStakingAbi,
    eventName: 'Approval',
    onLogs: (logs) => logs.forEach(listener),
  });
}

